// Shelf Audit: static client. Data lives in /data/*.json, regenerated by scripts/export.py
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const main=$('#main');
const D={};
const CH=['Woolworths',"Pak'nSave",'New World','FreshChoice'];
const CHCOL={'Woolworths':'#008446',"Pak'nSave":'#ffe14a','New World':'#ff4a36','FreshChoice':'#4a9bff'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>v==null?'n/a':'$'+v.toFixed(2);
const bigMoney=v=>v>=1e9?'$'+(v/1e9).toFixed(2).replace(/\.?0+$/,'')+' billion':v>=1e6?'$'+(v/1e6).toFixed(1).replace(/\.0$/,'')+' million':'$'+Math.round(v).toLocaleString('en-NZ');
const num=v=>Number(v).toLocaleString('en-NZ');
const nzDate=iso=>new Date(iso).toLocaleString('en-NZ',{timeZone:'Pacific/Auckland',day:'numeric',month:'short',year:'numeric'});
const nzTime=iso=>new Date(iso).toLocaleString('en-NZ',{timeZone:'Pacific/Auckland',day:'numeric',month:'short',hour:'numeric',minute:'2-digit'})+' NZT';
const cls=ix=>ix==null?'nu':ix>100.4?'up':ix<99.6?'dn':'nu';
const ixWord=ix=>ix==null?'not enough data':ix>100.4?`${(ix-100).toFixed(1)}% above the national median`:ix<99.6?`${(100-ix).toFixed(1)}% below the national median`:'about the national median';
const km=(a,b,c,d)=>{const R=6371,t=Math.PI/180,x=Math.sin((c-a)*t/2)**2+Math.cos(a*t)*Math.cos(c*t)*Math.sin((d-b)*t/2)**2;return 2*R*Math.asin(Math.sqrt(x))};
const store=id=>D.stores[id];
const LOGO={'Woolworths':'woolworths',"Pak'nSave":'paknsave','New World':'newworld','FreshChoice':'freshchoice','Four Square':'foursquare'};
const ini=c=>esc((c.match(/[A-Z]/g)||['?']).join('').slice(0,2));
const chOf=n=>{n=String(n||'').toLowerCase().replace(/[^a-z]/g,'');return Object.keys(LOGO).find(c=>n.startsWith(c.toLowerCase().replace(/[^a-z]/g,'')))||''};
const heroLogo=c=>c?`<div class="hlogo">${chLogo(c).replace('class="clogo','class="clogo hero').replace('loading="lazy" ','')}</div>`:'';
const chLogo=c=>LOGO[c]&&c!=='Four Square'?`<img class="clogo" src="/logos/${LOGO[c]}.${c==="Pak'nSave"?'svg':'png'}" alt="${esc(c)}" height="24" loading="lazy" onerror="this.outerHTML='<span class=&quot;clogo ini&quot; style=&quot;background:${CHCOL[c]||'#888'}&quot;>${ini(c)}</span>'">`:`<span class="clogo ini" style="background:${CHCOL[c]||'#888'}">${ini(c)}</span>`;

const ls={get:(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}},set:(k,v)=>localStorage.setItem(k,JSON.stringify(v))};
let basket=ls.get('sa-basket',{});
let here=ls.get('sa-here',null);
const cache={};
const storePrices=id=>cache[id]??=fetch(`/data/s/${id}.json`).then(r=>r.ok?r.json():{}).catch(()=>({}));
function toast(t){const e=document.createElement('div');e.className='toast';e.textContent=t;e.setAttribute('role','status');document.body.append(e);setTimeout(()=>e.remove(),2200)}
function setTitle(t){document.title=t?`${t} | Shelf Audit`:'Shelf Audit: who charges you more for the same groceries'}

// ---------- charts ----------
function ixBar(label,ix,href,sub='',ch=''){
  const span=15, d=Math.max(-span,Math.min(span,(ix??100)-100)), w=Math.abs(d)/span*50;
  const left=d>=0?50:50-w, c=cls(ix);
  const tag=href?'a':'div';
  return `<${tag} class="bar" ${href?`href="${href}"`:''} aria-label="${esc(label)}, index ${ix??'n/a'}, ${ixWord(ix)}">
    <span class="lbl">${ch?chLogo(ch):''}${esc(label)}${sub?` <small>${esc(sub)}</small>`:''}</span>
    <span class="trk"><span class="fill ${c}" style="left:${left}%;width:${Math.max(w,.6)}%"></span><span class="mid"></span></span>
    <span class="v ${c}">${ix==null?'n/a':ix.toFixed(1)}</span></${tag}>`;
}
const legend=()=>`<div class="legend"><span><i style="background:var(--red)"></i>Dearer than national median</span><span><i style="background:var(--green)"></i>Cheaper</span><span><i style="background:var(--ink)"></i>Line = 100, the national median</span></div>`;
function lineChart(series,{h=240,fmt=v=>v,yLabel=''}={}){
  const W=640,H=h,P={l:46,r:12,t:14,b:28};
  const all=series.flatMap(s=>s.pts);if(!all.length)return'';
  const xs=all.map(p=>+new Date(p[0])),ys=all.map(p=>p[1]);
  let x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys);const pad=(y1-y0)*.1||1;y0-=pad;y1+=pad;
  const X=t=>P.l+(t-x0)/(x1-x0||1)*(W-P.l-P.r),Y=v=>H-P.b-(v-y0)/(y1-y0)*(H-P.t-P.b);
  let g='';for(let i=0;i<=4;i++){const v=y0+(y1-y0)*i/4;g+=`<line class="ax" x1="${P.l}" x2="${W-P.r}" y1="${Y(v)}" y2="${Y(v)}"/><text x="${P.l-6}" y="${Y(v)+4}" text-anchor="end">${fmt(v)}</text>`}
  const yr=new Date(x0).getFullYear(),yrs=[];for(let y=yr;y<=new Date(x1).getFullYear()+1;y++){const t=+new Date(y,0,1);if(t>=x0&&t<=x1)yrs.push(t)}
  yrs.forEach(t=>g+=`<text x="${X(t)}" y="${H-8}" text-anchor="middle">${new Date(t).getFullYear()}</text><line class="ax" x1="${X(t)}" x2="${X(t)}" y1="${P.t}" y2="${H-P.b}" stroke-dasharray="2 3"/>`);
  const paths=series.map(s=>{const d=s.pts.map((p,i)=>(i?'L':'M')+X(+new Date(p[0])).toFixed(1)+' '+Y(p[1]).toFixed(1)).join('');const last=s.pts[s.pts.length-1];
    return `<path d="${d}" fill="none" stroke="${s.c}" stroke-width="${s.w||2.5}" ${s.dash?'stroke-dasharray="5 4"':''} stroke-linejoin="round"/><circle cx="${X(+new Date(last[0]))}" cy="${Y(last[1])}" r="4" fill="${s.c}"/>`}).join('');
  return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(yLabel)}">${g}${paths}</svg>`;
}
function hist(spread){
  const tot=spread.reduce((a,b)=>a+b[1],0),mx=Math.max(...spread.map(s=>s[1]));
  return `<div class="bars">${spread.map(([b,n])=>`<div class="bar" style="grid-template-columns:90px 1fr 56px"><span class="lbl">${b==100?'100% or more':b==0?'under 10%':`${b} to ${b+9}%`}</span><span class="trk"><span class="fill ${b>=30?'up':'nu'}" style="left:0;width:${n/mx*100}%"></span></span><span class="v">${Math.round(n/tot*100)}%</span></div>`).join('')}</div>`;
}

// ---------- location ----------
function places(){
  if(D.places)return D.places;
  const m=new Map();
  for(const s of D.stores){if(s.la==null)continue;
    const k=s.t.toLowerCase();if(!m.has(k))m.set(k,{n:s.t,sub:s.r,la:[],lo:[]});const p=m.get(k);p.la.push(s.la);p.lo.push(s.lo);
    m.set('s'+s.id,{n:s.nm,sub:s.t,la:[s.la],lo:[s.lo],store:s.id})}
  return D.places=[...m.values()].map(p=>({...p,la:p.la.reduce((a,b)=>a+b)/p.la.length,lo:p.lo.reduce((a,b)=>a+b)/p.lo.length}));
}
function placeSearch(el,onPick){
  const inp=$('input',el),ul=document.createElement('ul');ul.className='sugg';ul.hidden=true;ul.setAttribute('role','listbox');el.append(ul);
  inp.addEventListener('input',()=>{const q=inp.value.trim().toLowerCase();if(q.length<2){ul.hidden=true;return}
    const r=places().filter(p=>p.n.toLowerCase().includes(q)||p.sub.toLowerCase().includes(q)).sort((a,b)=>(a.n.toLowerCase().startsWith(q)?0:1)-(b.n.toLowerCase().startsWith(q)?0:1)||(a.store!=null)-(b.store!=null)).slice(0,8);
    ul.innerHTML=r.length?r.map((p,i)=>`<li><button type="button" data-i="${i}">${esc(p.n)} <small>${esc(p.sub)}</small></button></li>`).join(''):'<li><button type="button" disabled>No match yet. Try a nearby town.</button></li>';
    ul.hidden=false;$$('button[data-i]',ul).forEach(b=>b.onclick=()=>{const p=r[b.dataset.i];ul.hidden=true;inp.value=p.n;setHere({la:p.la,lo:p.lo,n:p.n});onPick()})});
  inp.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('button[data-i]',ul)?.click()}if(e.key==='Escape')ul.hidden=true});
}
function setHere(h){here=h;ls.set('sa-here',h)}
function geolocate(cb){
  if(!navigator.geolocation){toast('Location is not available on this device');return}
  toast('Finding you');
  navigator.geolocation.getCurrentPosition(p=>{setHere({la:p.coords.latitude,lo:p.coords.longitude,n:'your location'});cb()},()=>toast('Location was blocked. Type a town instead.'),{timeout:10000});
}
const nearby=(n=12,maxKm=40)=>here?D.stores.filter(s=>s.la!=null).map(s=>({...s,d:km(here.la,here.lo,s.la,s.lo)})).filter(s=>s.d<=maxKm).sort((a,b)=>a.d-b.d).slice(0,n):[];
const locBox=(id='loc')=>`<form class="search" id="${id}" role="search" onsubmit="return false"><label class="skip" for="${id}-i">Town, suburb or store</label><input id="${id}-i" autocomplete="off" placeholder="Town, suburb or store" value="${here&&here.n!=='your location'?esc(here.n):''}"><button type="button" class="btn ghost" data-geo>Near me</button></form>`;
function wireLoc(id,cb){const el=$('#'+id);placeSearch(el,cb);$('[data-geo]',el).onclick=()=>geolocate(cb)}

// ---------- pages ----------
// ---------- v3 visual layer ----------
const reveal=()=>{const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('on');io.unobserve(e.target)}}),{threshold:.12});$$('main .blk,main .stats,main .chains,main .ph').forEach(e=>{e.classList.add('rv');io.observe(e)})};
addEventListener('pointermove',e=>{const r=document.documentElement.style;r.setProperty('--mx',e.clientX+'px');r.setProperty('--my',e.clientY+'px')},{passive:true});
function countUp(el){const to=parseFloat(el.dataset.to),dec=+(el.dataset.dec||0),suf=el.dataset.suf||'',t0=performance.now();const f=t=>{const p=Math.min((t-t0)/1600,1),v=to*(1-Math.pow(1-p,4));el.textContent=(dec?v.toFixed(dec):Math.round(v).toLocaleString('en-NZ'))+suf;if(p<1)requestAnimationFrame(f)};requestAnimationFrame(f)}
function wireCounts(){const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){countUp(e.target);io.unobserve(e.target)}}),{threshold:.5});$$('[data-to]').forEach(e=>io.observe(e))}
function tagField(cv){
  const ctx=cv.getContext('2d'),dpr=Math.min(devicePixelRatio||1,2),RM=matchMedia('(prefers-reduced-motion:reduce)').matches;
  let W,H,mx=-999,my=-999,vis=true;
  const rs=()=>{W=cv.clientWidth;H=cv.clientHeight;cv.width=W*dpr;cv.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)};rs();addEventListener('resize',rs);
  const pool=D.products.filter(p=>p[6]>=40&&p[3]>0).sort(()=>Math.random()-.5).slice(0,34);
  const T=pool.map((p,i)=>({x:Math.random()*W,y:Math.random()*H,vx:(Math.random()-.5)*.4,vy:(Math.random()-.5)*.4,r:(Math.random()-.5)*1.2,vr:(Math.random()-.5)*.005,s:.7+Math.random()*.9,hot:i%4===0,nm:p[0].replace(/\s+\d.*$/,'').slice(0,18),pr:p[3].toFixed(2)}));
  cv.parentNode.addEventListener('pointermove',e=>{const b=cv.getBoundingClientRect();mx=e.clientX-b.left;my=e.clientY-b.top},{passive:true});
  new IntersectionObserver(es=>vis=es[0].isIntersecting).observe(cv);
  const draw=()=>{
    if(!cv.isConnected)return;
    if(vis){ctx.clearRect(0,0,W,H);
      for(const t of T){const dx=t.x-mx,dy=t.y-my,d=Math.hypot(dx,dy);if(d<200){t.vx+=dx/d*.14;t.vy+=dy/d*.14;t.vr+=.001}
        t.vx*=.985;t.vy*=.985;if(!RM){t.x+=t.vx;t.y+=t.vy;t.r+=t.vr}
        if(t.x<-120)t.x=W+120;if(t.x>W+120)t.x=-120;if(t.y<-90)t.y=H+90;if(t.y>H+90)t.y=-90;
        ctx.save();ctx.translate(t.x,t.y);ctx.rotate(t.r);ctx.scale(t.s,t.s);ctx.globalAlpha=t.hot?.92:.3;
        ctx.fillStyle=t.hot?'#ffe14a':'#f4efe6';ctx.beginPath();ctx.roundRect(-70,-40,140,80,10);ctx.fill();
        ctx.fillStyle='#0b0b0c';ctx.beginPath();ctx.arc(-58,-28,4.5,0,6.3);ctx.fill();
        ctx.textAlign='center';ctx.font='700 11px Lato,Arial';ctx.fillText(t.nm.toUpperCase(),4,-18);ctx.font='900 34px Lato,Arial';ctx.fillText('$'+t.pr,4,22);ctx.restore()}}
    requestAnimationFrame(draw)};
  draw()}
function gapSlider(p){
  const cheap=store(p[8][0][0]),ratio=Math.round((p[5]/p[4]-1)*100);
  return `<div class="cmp" id="cmp" style="--p:50%"><div class="pn2">${esc(p[0])} · ${p[6]} stores</div>
  <div class="sd a"><small>Cheapest · ${esc(cheap.nm)}</small><span class="pr">${money(p[4])}</span></div>
  <div class="sd b"><small>Dearest store, as captured</small><span class="pr">${money(p[5])}</span></div><div class="kb"></div></div>
  <p class="fine" style="margin-top:12px">Drag to compare. The dearest store charges ${ratio}% more for the identical product. <a href="#/p/${D.products.indexOf(p)}">See every store</a>.</p>`}
function wireSlider(){const cm=$('#cmp');if(!cm)return;let dn=0;const mv=x=>{const b=cm.getBoundingClientRect();cm.style.setProperty('--p',Math.max(4,Math.min(96,(x-b.left)/b.width*100))+'%')};
  cm.addEventListener('pointerdown',e=>{dn=1;cm.setPointerCapture(e.pointerId);mv(e.clientX)});cm.addEventListener('pointermove',e=>{if(dn)mv(e.clientX)});cm.addEventListener('pointerup',()=>dn=0)}
const R={};
R['']=()=>{
  setTimeout(reportCard,0);
  setTitle();const m=D.meta,c=m.chains;
  const best=Object.entries(c).filter(x=>x[1].ix).sort((a,b)=>a[1].ix-b[1].ix);
  const wide=D.products.filter(p=>p[6]>=30).map(p=>p[5]/p[4]).sort((a,b)=>b-a);const medGap=wide[Math.floor(wide.length/2)];
  const ex=D.products.filter(p=>p[6]>=60&&p[4]>2).sort((a,b)=>b[5]/b[4]-a[5]/a[4])[0];
  const tk=D.products.filter(p=>p[6]>=50&&p[4]>1.5).sort((a,b)=>b[5]/b[4]-a[5]/a[4]).slice(0,24).map(p=>`<span>${esc(p[0])} <i>${money(p[4])}</i> to <i>${money(p[5])}</i></span>`).join('');
  main.innerHTML=`<div id="rcard"></div>
  <section class="hero2"><canvas id="tf" aria-hidden="true"></canvas>
    <div class="hero2-in">
      <p class="kicker">Independent price watchdog · New Zealand</p>
      <h1><span>Same <span class="o">product.</span></span><em>Different <span class="o">price.</span></em></h1>
      <p class="lede">We price-check identical groceries across ${num(m.stores)} supermarkets, store by store, so you can see which one near you charges less for your basket, and who is creeping prices up.</p>
      ${locBox('hloc')}
      <p class="fine">Pick a town or tap Near me. Your location stays on your device.</p>
    </div><div class="cue">SCROLL TO AUDIT</div>
  </section>
  <div class="mq" aria-hidden="true"><div>${tk}${tk}</div></div>
  <div class="stats">
    <div class="stat"><b data-to="${m.stores}">${num(m.stores)}</b><span>stores captured</span></div>
    <div class="stat"><b data-to="${(m.prices/1e6).toFixed(1)}" data-dec="1" data-suf="M">${(m.prices/1e6).toFixed(1)}M</b><span>shelf prices read</span></div>
    <div class="stat"><b data-to="${m.matched}">${num(m.matched)}</b><span>products matched across stores</span></div>
    <div class="stat"><b style="font-size:clamp(26px,4vw,40px)">${nzDate(m.last)}</b><span>latest capture</span></div>
  </div>
  <section class="blk pull"><p class="kicker">What if</p><blockquote><p>If just a quarter of supermarkets nudged prices up 3%, shoppers would pay about <span class="o">$211 million</span> a year more.</p></blockquote>
  <p class="fine">Hypothetical, not a claim about any store. Supermarket and grocery store sales were $28.13 billion in the year to March 2026 (GST exclusive), per the <a href="https://www.stats.govt.nz/information-releases/retail-trade-survey-march-2026-quarter/" rel="noopener">Stats NZ Retail Trade Survey</a>. $28.13 billion × 25% × 3% = $211 million. Assumes sales are shared evenly across stores.</p></section>
  <section class="blk"><div id="stbars"></div></section>
  <section class="blk" id="htop"></section>
  <section class="blk" id="hnear" ${here?'':'hidden'}></section>
  ${ex?`<section class="blk"><p class="kicker">Widest gap on a common item</p><h2>One product.<br>Two prices.</h2>${gapSlider(ex)}</section>`:''}
  <section class="blk">
    <p class="kicker">The big picture</p>
    <h2>Which chain<br>is cheapest?</h2>
    <p class="say">On the same products, ${esc(best[0][0])} averages ${(100-best[0][1].ix).toFixed(1)}% below the national median, and ${esc(best[best.length-1][0])} averages ${(best[best.length-1][1].ix-100).toFixed(1)}% above it.</p>
    <div class="chains">${[...CH].sort((a,b)=>(c[b].ix||0)-(c[a].ix||0)).map(n=>{const x=c[n];return `<div class="chain" style="border-top:8px solid ${CHCOL[n]}"><div class="note">${esc(n)}</div><div class="ix ${cls(x.ix)}">${x.ix?`<span data-to="${x.ix.toFixed(1)}" data-dec="1">${x.ix.toFixed(1)}</span>`:'n/a'} <small>index</small></div><div class="what">${x.ix?ixWord(x.ix):'Not enough matching products yet'}</div><div class="fine">${x.n} stores captured</div>${stamp(n)}</div>`}).join('')}</div>
    <div id="catgrid"></div><p class="fine" style="margin-top:14px">Index 100 is the national median price for each identical product. 90 means you pay about 10% less. <a href="#/method">How we work it out</a>.</p>
  </section>
  <section class="blk grid2">
    <div><p class="kicker">Why it matters</p><h2>The gap<br>is real</h2>
    <p class="say">Across products stocked in 30 or more stores, the dearest store typically charges ${Math.round((medGap-1)*100)}% more than the cheapest for the exact same item.</p></div>
    <div><p class="kicker">How often do prices differ?</p><h3>Gap between cheapest and dearest store, per product</h3>${hist(m.spread)}<p class="fine">Share of ${num(m.matched)} matched products.</p></div>
  </section>
  <section class="blk grid2">
    <a class="card" href="#/basket" style="text-decoration:none"><p class="kicker">Build my basket</p><h3>Add your usual shop. We total it at every store near you.</h3><p class="note">See the cheapest store for what you actually buy, and what you would save in a year.</p></a>
    <a class="card" href="#/uptickers" style="text-decoration:none"><p class="kicker">Uptickers watch</p><h3>Who is nudging prices up?</h3><p class="note">Daily captures track rises item by item. Anything unusual is flagged, never assumed.</p></a>
    <a class="card" href="#/dairy" style="text-decoration:none"><p class="kicker">Dairy forensics</p><h3>Where your $5.68 for milk goes</h3><p class="note">Farmgate to shelf, with the Fonterra milk price and global auction tracker.</p></a>
    <a class="card" href="#/league" style="text-decoration:none"><p class="kicker">League table</p><h3>Every store, dearest to cheapest</h3><p class="note">Nationally and in your town.</p></a>
  </section>`;
  wireLoc('hloc',()=>{location.hash='#/near'});
  if(here)renderNear($('#hnear'),6);
  topGaps($('#htop'));catGrid($('#catgrid'),[...CH].sort((a,b)=>(c[b].ix||0)-(c[a].ix||0)));
  tagField($('#tf'));wireSlider();
};
function renderNear(el,n=12){
  const s=nearby(n);el.hidden=false;
  if(!s.length){el.innerHTML='<div class="empty">No captured stores within 40 km yet. Try a bigger town nearby.</div>';return}
  const sorted=[...s].sort((a,b)=>(a.thin-b.thin)||((a.ix??999)-(b.ix??999)));
  el.innerHTML=`<p class="kicker">Near ${esc(here.n)}</p><h2>Cheapest stores near you</h2><p class="say">Ranked by price index on identical products. ${sorted[0].ix?`${esc(sorted[0].nm)} is the cheapest nearby, ${ixWord(sorted[0].ix)}.`:''}</p>
  <ol class="slist">${sorted.map((x,i)=>`<li><a href="#/store/${x.id}"><span class="rk">${i+1}</span>${chLogo(x.ch)}<span class="nm">${esc(x.nm)}${x.thin?'<span class="badge">thin data</span>':''}<span class="sub">${esc(x.ch)}, ${x.d.toFixed(1)} km away</span></span><span class="pill ${cls(x.ix)}">${x.ix?x.ix.toFixed(1):'n/a'}</span></a></li>`).join('')}</ol>
  <p style="margin-top:16px"><a class="btn" href="#/basket">Compare my basket at these stores</a></p>`;
}
R.near=()=>{setTitle('Stores near me');main.innerHTML=`<div class="ph"><p class="kicker">Store finder</p><h1 style="font-size:clamp(36px,7vw,64px)">Stores near me</h1>${locBox('nloc')}</div><section id="nres"></section>`;
  const go=()=>renderNear($('#nres'),15);wireLoc('nloc',go);if(here)go();else $('#nres').innerHTML='<div class="empty">Type your town or suburb, or tap Near me.</div>'};

// products
function prodRow(p,i){const inb=basket[i];return `<li><span class="pn"><a href="#/p/${i}">${esc(p[0])}</a><small>${esc(p[2])}, ${p[6]} stores</small></span><span class="range"><span class="dn">${money(p[4])}</span><br><small class="up">${p[5]>p[4]?'to '+money(p[5]):''}</small></span><button class="add ${inb?'in':''}" data-add="${i}" aria-label="${inb?'Remove from':'Add to'} basket: ${esc(p[0])}">${inb?'✓':'+'}</button></li>`}
function wireAdd(root=main){$$('[data-add]',root).forEach(b=>b.onclick=()=>{const i=b.dataset.add;if(basket[i])delete basket[i];else basket[i]=1;ls.set('sa-basket',basket);b.classList.toggle('in',!!basket[i]);b.textContent=basket[i]?'✓':'+';toast(basket[i]?'Added to basket':'Removed');basketBar()})}
function searchProducts(q,cat){q=q.toLowerCase().trim();const w=q.split(/\s+/).filter(Boolean);
  const r=[];D.products.forEach((p,i)=>{if(cat&&p[2]!==cat)return;const n=(p[0]+' '+p[1]).toLowerCase();if(w.every(x=>n.includes(x)))r.push(i)});return r}
R.products=(q='')=>{setTitle('Products');q=decodeURIComponent(q||'');const cats=[...new Set(D.products.map(p=>p[2]))].sort();
  main.innerHTML=`<div class="ph"><p class="kicker">Product search</p><h1 style="font-size:clamp(36px,7vw,64px)">Find a product</h1>
  <p class="note">${num(D.products.length)} of the most widely stocked identical products, priced across every captured store.</p>
  <form class="search" onsubmit="return false" role="search"><label class="skip" for="pq">Search products</label><input id="pq" placeholder="e.g. anchor milk 2l, weet-bix, butter" value="${esc(q)}"></form>
  <div class="chips" id="cats"><button class="chip" aria-pressed="true" data-c="">All</button>${cats.map(c=>`<button class="chip" aria-pressed="false" data-c="${esc(c)}">${esc(c)}</button>`).join('')}</div></div>
  <ul class="plist" id="pl"></ul>`;
  let cat='';const run=()=>{const r=searchProducts($('#pq').value,cat);$('#pl').innerHTML=r.slice(0,80).map(i=>prodRow(D.products[i],i)).join('')||'<li class="empty">No match. Try fewer words.</li>';wireAdd()};
  $('#pq').oninput=run;$$('#cats .chip').forEach(b=>b.onclick=()=>{cat=b.dataset.c;$$('#cats .chip').forEach(x=>x.setAttribute('aria-pressed',x===b));run()});run();
};
R.p=async id=>{const p=D.products[+id];if(!p)return R.notfound();setTitle(p[0]);
  const chm=Object.entries(p[7]),mx=Math.max(...chm.map(x=>x[1]));
  main.innerHTML=`<p class="crumb"><a href="#/products">Products</a></p><div class="ph"><p class="kicker">${esc(p[2])} · ${esc(p[1])}</p><h1 style="font-size:clamp(32px,6vw,56px)">${esc(p[0])}</h1>
  <p class="say">Stocked in ${p[6]} captured stores. Cheapest ${money(p[4])}, dearest ${money(p[5])}, typical ${money(p[3])}.</p>
  <button class="btn" data-add="${id}">${basket[id]?'In your basket':'Add to my basket'}</button>${fieldFor('p',+id)}</div>
  <section class="blk grid2"><div><h3>Typical price by chain</h3><div class="bars">${chm.sort((a,b)=>a[1]-b[1]).map(([c,v])=>`<div class="bar"><span class="lbl">${esc(c)}</span><span class="trk"><span class="fill" style="left:0;width:${v/mx*100}%;background:${CHCOL[c]}"></span></span><span class="v">${money(v)}</span></div>`).join('')}</div><p class="fine">Median shelf price across that chain's captured stores.</p></div>
  <div><h3>Cheapest stores</h3><ol class="slist">${p[8].map(([s,v],i)=>`<li><a href="#/store/${s}"><span class="rk">${i+1}</span>${chLogo(store(s).ch)}<span class="nm">${esc(store(s).nm)}<span class="sub">${esc(store(s).t)}</span></span><span class="pill dn">${money(v)}</span></a></li>`).join('')}</ol></div></section>
  <section class="blk" id="pchain"></section><section class="blk" id="pnear"></section>`;
  wireAdd();prodChain(id);
  const s=nearby(10);if(s.length){const pr=await Promise.all(s.map(x=>storePrices(x.id)));const rows=s.map((x,i)=>{const v=pr[i][id];return v==null?null:[x,Array.isArray(v)?v[0]:v,Array.isArray(v)]}).filter(Boolean).sort((a,b)=>a[1]-b[1]);
    $('#pnear').innerHTML=`<h3>Near ${esc(here.n)}</h3>${rows.length?`<ol class="slist">${rows.map(([x,v,sp],i)=>`<li><a href="#/store/${x.id}"><span class="rk">${i+1}</span>${chLogo(x.ch)}<span class="nm">${esc(x.nm)}${sp?'<span class="badge">special</span>':''}<span class="sub">${x.d.toFixed(1)} km</span></span><span class="pill ${i===0?'dn':v>rows[0][1]?'up':'nu'}">${money(v)}</span></a></li>`).join('')}</ol>`:'<p class="note">Not captured at stores near you yet.</p>'}`}
  else $('#pnear').innerHTML=`<p class="note"><a href="#/near">Set your location</a> to see this product at stores near you.</p>`;
};

// basket
function basketBar(){$('.basketbar')?.remove();const n=Object.keys(basket).length;if(!n||location.hash.startsWith('#/basket'))return;const a=document.createElement('a');a.className='basketbar';a.href='#/basket';a.textContent=`My basket (${n}) · compare`;document.body.append(a)}
const STARTER=['anchor blue milk 2l','weet-bix','tip top bread','mainland butter','pams free range eggs','bananas'];
R.basket=async()=>{setTitle('My basket');const ids=Object.keys(basket);
  main.innerHTML=`<div class="ph"><p class="kicker">Build my basket</p><h1 style="font-size:clamp(36px,7vw,64px)">What does your shop cost?</h1><p class="lede">Add what you usually buy. We total it at every store near you, like for like.</p></div>
  <div class="grid2"><div><div class="receipt"><h3>Your basket</h3><div id="bitems"></div></div>
  <form class="search" onsubmit="return false" style="margin-top:26px"><label class="skip" for="bq">Add a product</label><input id="bq" placeholder="Add a product, e.g. milk"></form><ul class="plist" id="bres"></ul>
  ${ids.length?'':`<p class="note">Not sure where to start? <button class="btn sm ghost" id="starter">Load a starter basket</button></p>`}</div>
  <div><h3>Where it is cheapest</h3>${locBox('bloc')}<div id="bcmp" class="results"></div></div></div>`;
  const items=()=>{const ids=Object.keys(basket);$('#bitems').innerHTML=ids.length?ids.map(i=>{const p=D.products[i];return `<div class="ritem"><span>${esc(p[0])}</span><span class="qty"><button data-q="${i}" data-d="-1" aria-label="Less">-</button>${basket[i]}<button data-q="${i}" data-d="1" aria-label="More">+</button></span><button data-x="${i}" aria-label="Remove ${esc(p[0])}">×</button></div>`}).join('')+`<div class="total"><span>${ids.length} items</span><span>typical ${money(ids.reduce((a,i)=>a+D.products[i][3]*basket[i],0))}</span></div>`:'<p class="note" style="text-align:center">Empty. Search below to add items.</p>';
    $$('[data-q]').forEach(b=>b.onclick=()=>{const i=b.dataset.q;basket[i]=Math.max(1,basket[i]+ +b.dataset.d);ls.set('sa-basket',basket);items();cmp()});
    $$('[data-x]').forEach(b=>b.onclick=()=>{delete basket[b.dataset.x];ls.set('sa-basket',basket);items();cmp()})};
  $('#bq').oninput=()=>{const q=$('#bq').value;$('#bres').innerHTML=q.length<2?'':searchProducts(q).slice(0,8).map(i=>prodRow(D.products[i],i)).join('');wireAdd($('#bres'));$$('#bres [data-add]').forEach(b=>b.addEventListener('click',()=>{items();cmp()}))};
  $('#starter')&&($('#starter').onclick=()=>{STARTER.forEach(q=>{const r=searchProducts(q);if(r.length)basket[r[0]]=1});ls.set('sa-basket',basket);R.basket()});
  const cmp=async()=>{const el=$('#bcmp'),ids=Object.keys(basket);
    if(!ids.length){el.innerHTML='<div class="empty">Add items to compare.</div>';return}
    if(!here){el.innerHTML='<div class="empty">Set your town to compare stores near you.</div>';return}
    const s=nearby(12).filter(x=>!x.thin||nearby(12).every(y=>y.thin));if(!s.length){el.innerHTML='<div class="empty">No stores captured near here yet.</div>';return}
    el.innerHTML='<p class="note">Totalling</p>';const pr=await Promise.all(s.map(x=>storePrices(x.id)));
    const val=(m,i)=>{const v=m[i];return v==null?null:Array.isArray(v)?v[0]:v};
    const common=ids.filter(i=>pr.filter(m=>val(m,i)!=null).length>=Math.max(2,Math.ceil(s.length*.6)));
    const rows=s.map((x,k)=>{const have=common.filter(i=>val(pr[k],i)!=null);const t=have.reduce((a,i)=>a+val(pr[k],i)*basket[i],0);return {x,t,have:have.length,full:have.length===common.length}}).filter(r=>r.have>0);
    const full=rows.filter(r=>r.full).sort((a,b)=>a.t-b.t),part=rows.filter(r=>!r.full).sort((a,b)=>b.have-a.have);
    if(!full.length){el.innerHTML='<div class="empty">No nearby store stocks all of these items in our data. Try removing a niche item.</div>';return}
    const lo=full[0].t,hi=full[full.length-1].t,sav=hi-lo;
    el.innerHTML=`<p class="say">${esc(full[0].x.nm)} is cheapest for ${common.length===ids.length?'your basket':`the ${common.length} items most stores stock`}. ${sav>0.005?`That is ${money(sav)} less than the dearest nearby store, about ${bigMoney(sav*52)} a year if you shop weekly.`:''}</p>`+
      full.map((r,i)=>`<a class="res ${i===0?'best':''}" href="#/store/${r.x.id}"><span><strong>${esc(r.x.nm)}</strong><br><span class="meta">${r.x.d.toFixed(1)} km · ${esc(r.x.ch)}</span></span><span class="amt ${i===0?'dn':r.t-lo>0.005?'up':''}">${money(r.t)}</span>${i>0&&r.t-lo>0.005?`<span class="save up">+${money(r.t-lo)} more than ${esc(full[0].x.nm)}</span>`:i===0?'<span class="save dn">Cheapest near you</span>':''}</a>`).join('')+
      (part.length?`<p class="fine">${part.length} nearby stores are left out because they did not have every item in our capture.</p>`:'')+
      (common.length<ids.length?`<p class="fine">${ids.length-common.length} of your items are left out of the totals because fewer than 60% of these stores stock them.</p>`:'')+
      '<p class="fine">Shelf prices as captured, including any specials on the day. Not a quote.</p>'};
  wireLoc('bloc',cmp);items();cmp();
};

// league
R.league=(q='')=>{setTitle('League table');const params=new URLSearchParams(decodeURIComponent(q||''));
  const regions=[...new Set(D.stores.map(s=>s.r).filter(Boolean))].sort(),towns=[...new Set(D.stores.filter(s=>s.ix&&!s.thin).map(s=>s.t))].sort();
  main.innerHTML=`<div class="ph"><p class="kicker">League table</p><h1 style="font-size:clamp(36px,7vw,64px)">Dearest to cheapest</h1><p class="lede">Every store with enough matched products, ranked on the same items.</p>
  <div class="chips"><select id="lc" aria-label="Chain"><option value="">All chains</option>${CH.map(c=>`<option>${esc(c)}</option>`).join('')}</select><select id="lr" aria-label="Region"><option value="">All of New Zealand</option>${regions.map(c=>`<option>${esc(c)}</option>`).join('')}</select><select id="lt" aria-label="Town"><option value="">Any town</option>${towns.map(c=>`<option>${esc(c)}</option>`).join('')}</select><label class="chip"><input type="checkbox" id="lthin"> include thin data</label></div></div>
  <section><p class="say" id="lsay"></p>${legend()}<div class="bars" id="lb"></div></section>`;
  ['lc','lr','lt'].forEach(k=>{const v=params.get(k);if(v)$('#'+k).value=v});
  const run=()=>{const c=$('#lc').value,r=$('#lr').value,t=$('#lt').value,th=$('#lthin').checked;
    const s=D.stores.filter(x=>x.ix&&(th||!x.thin)&&(!c||x.ch===c)&&(!r||x.r===r)&&(!t||x.t===t)).sort((a,b)=>b.ix-a.ix);
    $('#lsay').textContent=s.length?`${s.length} stores. Dearest: ${s[0].nm} (${s[0].ix.toFixed(1)}). Cheapest: ${s[s.length-1].nm} (${s[s.length-1].ix.toFixed(1)}).`:'No stores match. FreshChoice stores are all thin data so far; tick include thin data.';
    $('#lb').innerHTML=s.map(x=>ixBar(x.nm,x.ix,`#/store/${x.id}`,x.t!==x.nm.replace(/^\S+\s/,'')?x.t:'',x.ch)).join('')};
  $$('select,#lthin').forEach(e=>e.onchange=run);run();
};

// store
const WATCH={"Pak'nSave Silverdale":'Fined $234,000 in October 2026 over pricing at this store, per the Commerce Commission case. Listed for closer monitoring.',"Pak'nSave Mill Street":'Fined $346,500 in October 2026 over pricing at this store, per the Commerce Commission case. Listed for closer monitoring.','New World Waiuku':'Listed for closer monitoring. No finding is implied.','New World Papatoetoe':'Listed for closer monitoring. No finding is implied.'};
const watchStore=n=>D.stores.find(s=>s.nm.toLowerCase().replace(/[^a-z]/g,'').includes(n.toLowerCase().replace(/[^a-z]/g,'').replace('street','st'))||s.nm.toLowerCase().replace(/[^a-z]/g,'').includes(n.toLowerCase().replace(/[^a-z]/g,'')));
R.store=id=>{const s=store(+id);if(!s)return R.notfound();setTitle(s.nm);setTimeout(()=>storeNat(s),0);
  const w=Object.entries(WATCH).find(([n])=>watchStore(n)===s);
  const cats=Object.entries(s.cats).sort((a,b)=>b[1]-a[1]);
  const peers=s.la!=null?D.stores.filter(x=>x.id!==s.id&&x.la!=null&&x.ix&&!x.thin).map(x=>({...x,d:km(s.la,s.lo,x.la,x.lo)})).filter(x=>x.d<25).sort((a,b)=>a.d-b.d).slice(0,8):[];
  const rank=D.stores.filter(x=>x.ix&&!x.thin).sort((a,b)=>a.ix-b.ix).findIndex(x=>x.id===s.id);
  main.innerHTML=`<p class="crumb"><a href="#/league">League table</a></p><div class="ph">${heroLogo(s.ch)}<p class="kicker" style="color:${CHCOL[s.ch]}">${esc(s.ch)} · ${esc(s.t)}${s.r?', '+esc(s.r):''}</p><h1 style="font-size:clamp(34px,7vw,64px)">${esc(s.nm)}</h1>
  ${fieldStore(s.id)}${w?`<p><span class="badge flag">Under watch</span> <span class="note">${esc(w[1])}</span></p>`:''}
  <div class="stats" style="border-top:2px solid var(--ink)"><div class="stat"><b class="${cls(s.ix)}">${s.ix?s.ix.toFixed(1):'n/a'}</b><span>price index</span></div><div class="stat"><b>${s.above??'n/a'}%</b><span>of items above national median</span></div><div class="stat"><b>${num(s.m)}</b><span>matched products</span></div><div class="stat"><b>${rank>=0?`${rank+1} of ${D.meta.full}`:'n/a'}</b><span>cheapest nationally</span></div></div>
  <p class="say" style="margin-top:20px"><span id="sword">${s.ix?`On identical products, this store is ${ixWord(s.ix)}.`:'Not enough matched products to rank this store.'}</span> <span id="sthin">${s.thin?'Thin data: fewer than 1,000 matched products, so treat the index as a rough guide.':''}</span></p><div id="scost">${s.ix?lifeCost(s.ix-100,'the national median for the same products'):''}</div><p class="fine">Captured ${nzTime(s.at)}.</p></div><div class="blk" id="sov"></div>
  ${cats.length?`<section class="blk"><h3>By aisle</h3><p class="note">Index for each category against the national median.</p>${legend()}<div class="bars">${cats.map(([c,v])=>ixBar(c,v)).join('')}</div></section>`:''}
  ${peers.length?`<section class="blk"><h3>Compared with stores nearby</h3>${legend()}<div class="bars">${[{...s,d:0},...peers].sort((a,b)=>b.ix-a.ix).map(x=>ixBar(x.id===s.id?x.nm+' (this store)':x.nm,x.ix,`#/store/${x.id}`,x.id===s.id?'':x.d.toFixed(1)+' km',x.ch)).join('')}</div></section>`:''}
  <section class="blk"><a class="btn" href="#/basket">Price my basket here and nearby</a></section>`;
  if(s.la!=null&&!here){/* allow quick set */}
};

// uptickers
R.uptickers=()=>{setTitle('Uptickers watch');const sh=D.dairy.shelf,dates=[...new Set(sh.map(x=>x.date))].sort();
  const last=dates[dates.length-1],prev=dates[dates.length-2];
  const ch=sh.filter(x=>x.date===last).map(x=>{const o=sh.find(y=>y.date===prev&&y.item===x.item&&y.chain===x.chain);return {...x,was:o?.median_price_nzd}}).filter(x=>x.was!=null);
  const gaps=D.products.map((p,i)=>[p,i]).filter(([p])=>p[6]>=40&&p[4]>=2).sort((a,b)=>b[0][5]/b[0][4]-a[0][5]/a[0][4]).slice(0,15);
  main.innerHTML=`<div class="ph"><p class="kicker">Uptickers watch</p><h1 style="font-size:clamp(36px,7vw,64px)">Who is nudging prices up?</h1><p class="lede">An Upticker is a store whose shelf prices on identical items rise faster than the rest of the country. We capture prices repeatedly and compare each item with itself.</p></div>
  <section class="blk"><div class="card"><p class="kicker">Status</p><h3>National tracking is warming up</h3><p class="note">The first full national capture ran ${nzDate(D.meta.first)} to ${nzDate(D.meta.last)}. Store-by-store rises appear here once the second national pass lands. Until then, the dairy basket below is tracked daily.</p></div></section>
  <section class="blk"><h2>Dairy basket, day on day</h2><p class="say">Median shelf price by chain, ${esc(prev||'')} to ${esc(last)}.</p>
  <div class="tblwrap"><table class="table"><thead><tr><th>Item</th><th>Chain</th><th class="n">Before</th><th class="n">Now</th><th class="n">Change</th></tr></thead><tbody>${ch.map(x=>{const d=x.median_price_nzd-x.was;return `<tr><td>${esc(x.item)}</td><td>${esc(x.chain)}</td><td class="n">${money(x.was)}</td><td class="n">${money(x.median_price_nzd)}</td><td class="n ${d>0.004?'up':d<-0.004?'dn':''}">${Math.abs(d)<0.005?'no change':(d>0?'+':'-')+money(Math.abs(d))}</td></tr>`}).join('')}</tbody></table></div></section>
  <section class="blk"><h2>Biggest gaps on the same product</h2><p class="say">These items are stocked in 40 or more stores and show the widest gap between the cheapest and dearest shelf. Flagged for a closer look; specials can explain some of it.</p>
  <ul class="plist">${gaps.map(([p,i])=>`<li><span class="pn"><a href="#/p/${i}">${esc(p[0])}</a><small>${p[6]} stores · dearest is ${Math.round((p[5]/p[4]-1)*100)}% above cheapest</small></span><span class="range"><span class="dn">${money(p[4])}</span><br><small class="up">to ${money(p[5])}</small></span><button class="add ${basket[i]?'in':''}" data-add="${i}" aria-label="Add ${esc(p[0])}">${basket[i]?'✓':'+'}</button></li>`).join('')}</ul></section>
  <section class="blk prose"><h3>How we flag</h3><p>A store is flagged when the same item rises at that store but not across its chain, or when its index climbs over several captures. A flag is a prompt to look closer. It is not a finding of wrongdoing, and a single capture can include a special ending or a data error.</p></section>`;wireAdd();overList(s.id,$('#sov'))};

// dairy
R.dairy=()=>{setTitle('Dairy chain');const d=D.dairy,f=d.fonterra,g=d.gdt;const lf=f[f.length-1];
  const gi=g.map(x=>[x.date,x.index_level]).filter(x=>x[1]),gb=g.filter(x=>x.butter_usd_t).map(x=>[x.date,x.butter_usd_t]);
  const lastShelf=d.shelf.filter(x=>x.date===d.shelf[d.shelf.length-1].date);
  const split=(parts,total)=>`<div class="split">${parts.map(p=>`<div style="flex:${p[1]};background:${p[2]}" title="${esc(p[0])}">${p[1]/total>.12?'$'+p[1].toFixed(2):''}</div>`).join('')}</div><div class="keys">${parts.map(p=>`<span><i style="background:${p[2]}"></i>${esc(p[0])} <b>$${p[1].toFixed(2)}</b></span>`).join('')}</div>`;
  main.innerHTML=`<div class="ph"><p class="kicker">Dairy forensics</p><h1 style="font-size:clamp(36px,7vw,64px)">Where your dairy dollar goes</h1><p class="lede">From the farm gate to the supermarket shelf, using Fonterra's milk price, global auction prices and our own shelf captures.</p></div>
  ${d.milk2l?`<section class="blk"><h2>Milk: cheapest and dearest in NZ</h2><div class="grid2"><div class="card" style="border-left:6px solid #1d6b45"><p class="kicker" style="color:#1d6b45">Cheapest 2L milk in NZ</p>${heroLogo(chOf(d.milk2l.cheapest.store))}<h3 style="font-size:40px;margin:4px 0">${money(d.milk2l.cheapest.price)}</h3><p><b>${esc(d.milk2l.cheapest.store)}</b>, ${esc(d.milk2l.cheapest.town)}</p><p class="note">${esc(d.milk2l.cheapest.product)}. Next best: ${esc(d.milk2l.cheapest.next)}. Cheapest Anchor Blue 2L: ${money(d.milk2l.blue_cheapest.price)} at every Pak'nSave.</p></div><div class="card" style="border-left:6px solid #c8361f"><p class="kicker" style="color:#c8361f">Dearest Anchor Blue 2L in NZ</p>${heroLogo(chOf(d.milk2l.blue_dearest.store))}<h3 style="font-size:40px;margin:4px 0;color:#c8361f">${money(d.milk2l.blue_dearest.price)}</h3><p><b>${esc(d.milk2l.blue_dearest.store)}</b></p><p class="note">Same bottle is ${money(d.milk2l.blue_cheapest.price)} at Pak'nSave and $5.68 at North Island Woolworths and New World. Dearest Anchor Blue vs cheapest standard 2L: ${money(d.milk2l.blue_dearest.price-d.milk2l.cheapest.price)} a bottle.</p></div></div><p class="fine">Regular shelf prices from the national capture, ${esc(d.milk2l.captured)}, 450 stores. FreshChoice stores did not list 2L milk online.</p></section>`:''}
  <section class="blk"><h2>A 2L bottle of Anchor Blue, $5.68</h2><p class="say">The farmer gets about $1.69. GST is $0.74. About $3.25 goes to processing, packing, freight and the shop.</p>
  ${split([['Farmer',1.69,'#1d6b45'],['Processing, packing, freight',2.13,'#857c70'],['Retail margin',1.12,'#c8361f'],['GST',0.74,'#141210']],5.68)}
  <p class="fine">Estimate. Farmgate $9.69 per kgMS (2025/26), about 11.5 litres per kgMS. Retail share uses Woolworths NZ's company-wide gross margin of 22.7%, not a dairy-only figure. No company publishes how the middle $2.13 splits.</p></section>
  <section class="blk grid2"><div><h3>Anchor butter 500g, $8.50</h3>${split([['World wholesale value',4.07,'#1d6b45'],['Supplier, packing, freight',1.64,'#857c70'],['Retail margin',1.68,'#c8361f'],['GST',1.11,'#141210']],8.5)}</div>
  <div><h3>Mainland Colby 1kg, $18.95</h3>${split([['World wholesale value',6.28,'#1d6b45'],['Supplier, packing, freight',6.46,'#857c70'],['Retail margin',3.74,'#c8361f'],['GST',2.47,'#141210']],18.95)}</div>
  <p class="fine" style="grid-column:1/-1">Estimates at Woolworths shelf prices. Wholesale value from the GDT auction of 20 Oct 2026 at an assumed NZ$1 = US$0.58.</p></section>
  <section class="blk grid2"><div><p class="kicker">Fonterra farmgate milk price</p><h3>Forecast midpoint, $ per kgMS</h3>${lineChart([{pts:f.map(x=>[x.date,x.midpoint]),c:'#1d6b45'}],{fmt:v=>'$'+v.toFixed(2),yLabel:'Fonterra forecast midpoint'})}<p class="say">Latest: $${lf.midpoint.toFixed(2)} for ${esc(lf.season)}, range $${lf.range_low.toFixed(2)} to $${lf.range_high.toFixed(2)} (${nzDate(lf.date)}).</p></div>
  <div><p class="kicker">Global Dairy Trade auction</p><h3>Butter, US$ per tonne</h3>${lineChart([{pts:gb,c:'#c8361f'}],{fmt:v=>'$'+Math.round(v/100)/10+'k',yLabel:'GDT butter price'})}<p class="say">World butter fell from US$7,992 a tonne (May 2025 peak) to US$${num(gb[gb.length-1][1])} on ${nzDate(gb[gb.length-1][0])}. Shelf butter is still $8.29 to $10.50 a block.</p></div></section>
  <section class="blk"><h3>GDT price index</h3>${lineChart([{pts:gi,c:'#141210'}],{h:200,fmt:v=>Math.round(v),yLabel:'GDT index'})}<p class="fine">${g.length} auction events captured. Latest index ${g[g.length-1].index_level} (${g[g.length-1].index_change_pct>0?'+':''}${g[g.length-1].index_change_pct}%).</p></section>
  <section class="blk"><h3>Shelf prices today, by chain</h3><div class="tblwrap"><table class="table"><thead><tr><th>Item</th><th>Chain</th><th class="n">Median</th><th class="n">Stores</th></tr></thead><tbody>${lastShelf.map(x=>`<tr><td>${esc(x.item)}</td><td>${esc(x.chain)}</td><td class="n">${money(x.median_price_nzd)}</td><td class="n">${x.stores}</td></tr>`).join('')}</tbody></table></div>
  <p class="note">Within each chain, dairy prices barely change by town. The gap is between chains, not between places.</p></section>
  <section class="blk"><h3>Who earns what</h3><div class="tblwrap"><table class="table"><thead><tr><th>Company</th><th>Year</th><th class="n">Sales</th><th class="n">Operating profit (EBIT)</th><th class="n">EBIT margin</th></tr></thead><tbody>
  <tr><td>Fonterra</td><td>FY25</td><td class="n">$26 billion</td><td class="n">$1.73 billion</td><td class="n">6.7%</td></tr>
  <tr><td>Fonterra</td><td>FY26</td><td class="n">$27 billion</td><td class="n">$3.4 billion</td><td class="n">12.6%</td></tr>
  <tr><td>Woolworths NZ</td><td>F25</td><td class="n">$8.29 billion</td><td class="n">$150 million</td><td class="n">1.8%</td></tr>
  <tr><td>Woolworths NZ</td><td>F26</td><td class="n">$8.49 billion</td><td class="n">$163 million</td><td class="n">1.9%</td></tr></tbody></table></div>
  <p class="fine">From each company's own reports. Fonterra FY26 includes a $1.2 billion one-off gain from the Mainland sale; underlying operating profit was $1.8 billion. Foodstuffs reports small profits after rebates to its owner-operators, so store-level profit is not visible.</p></section>
  <p class="fine">Dairy data updated ${esc(d.updated)}. Sources: fonterra.com, globaldairytrade.info, Stats NZ, company annual reports, Shelf Audit captures.</p>`};

R.watch=()=>{setTitle('Stores under watch');main.innerHTML=`<div class="ph"><p class="kicker">Watchlist</p><h1 style="font-size:clamp(36px,7vw,64px)">Stores under watch</h1><p class="lede">Stores we capture more often because of a past regulatory case or a pattern worth checking. Being listed is not an allegation.</p></div>
  <div class="results">${Object.entries(WATCH).map(([n,t])=>{const s=watchStore(n);return `<${s?`a href="#/store/${s.id}"`:'div'} class="res"><span><strong>${esc(n)}</strong><br><span class="meta">${esc(t)}</span></span><span class="amt ${s?cls(s.ix):''}">${s&&s.ix?s.ix.toFixed(1):'pending'}</span></${s?'a':'div'}>`}).join('')}</div><p class="fine">Number shown is the store's price index. Pending means the store is not in the current capture yet.</p>`};

R.method=()=>{setTitle('Method and freshness');const m=D.meta;main.innerHTML=`<div class="ph prose"><p class="kicker">Method</p><h1 style="font-size:clamp(36px,7vw,64px)">How Shelf Audit works</h1></div>
  <div class="stats"><div class="stat"><b>${nzDate(m.first)}</b><span>capture started</span></div><div class="stat"><b>${nzDate(m.last)}</b><span>latest store captured</span></div><div class="stat"><b>${num(m.full)}</b><span>stores with full data</span></div><div class="stat"><b>${num(m.cross)}</b><span>products matched across chains</span></div></div>
  <div class="prose"><h2>1. Capture</h2><p>We read the public online shelf price for every product at each store's own online shop: Woolworths, New World, Pak'nSave and FreshChoice (including SuperValue). Each capture is time-stamped and hash-chained, so a later edit would show.</p>
  <h2>2. Match identical products</h2><p>Foodstuffs stores share product codes. Across chains we match on brand words and pack size, for example "Anchor Blue Milk 2L". Products in fewer than five stores, or with a price gap over four times, are left out as likely mismatches.</p>
  <h2>3. Index</h2><p>For each product we take the national median price. A store's index is the average of its price divided by that median, times 100. So 100 is typical, 90 means about 10% cheaper, 105 means about 5% dearer. Stores with fewer than 1,000 matched products are marked thin data.</p>
  <h2 id="near">Drive time and savings nearby</h2><p>For the worst-graded store we list up to six cheaper supermarkets within 25 km. Drive time and distance are one way by road, from OpenStreetMap road data through the public OSRM router, without live traffic. Saving a week = typical shop $214.10 × (worst store national index minus nearby store national index) ÷ 100. A year is 52 weeks. Fuel and time cost are not included.</p>
  <h2 id="life">What a dear store costs</h2><p>To make an index real, we turn it into dollars, hours and groceries. We take a typical weekly supermarket shop and add the store's gap above the median. Extra a week = $214.10 × gap %. A year is 52 weeks. Hours of work = extra ÷ hourly wage. Groceries = yearly extra ÷ the median shelf price of that item. One source of truth: the gap is always the store's national price index (regular shelf prices, 100 = typical NZ price for the same products) minus 100. The report card, drive-and-save block and store pages all use this same figure.</p>
  <ul><li><b>Typical shop $214.10 a week</b>: Stats NZ Household Economic Survey, year ended June 2023, average weekly household spend on grocery food ($139.40), meat, poultry and fish ($31.40), fruit and vegetables ($27.70) and non-alcoholic drinks ($15.60). Restaurant and takeaway food is left out. These are 2023 dollars, so the real figure today is likely higher and our estimate is conservative.</li>
  <li><b>Minimum wage $23.95 an hour</b>: adult rate from 1 April 2026, Minimum Wage Order 2026 (employment.govt.nz).</li>
  <li><b>Median wage $35.96 an hour</b>: Stats NZ, Labour market statistics (income), June 2026 quarter, median hourly earnings from wages and salaries.</li>
  <li><b>Living Wage $29.90 an hour</b>: Living Wage Movement Aotearoa, from 1 September 2026, for reference.</li>
  <li><b>Groceries</b>: Shelf Audit captures, November 2026. Anchor Blue 2L milk $5.68, Nature's Fresh white bread 700g $3.99 (national median), Farmer Brown barn eggs 12 pack $7.40 (national median).</li></ul>
  <p>This is an estimate for a household that does its whole shop at one store. Real baskets differ, and the index covers matched products only. It shows scale, it is not a bill.</p>
  <h2>4. Basket</h2><p>Your basket is totalled only on items every compared store stocks, so totals are like for like. Specials on the capture day are included because that is what you would have paid.</p>
  <h2>5. Uptickers</h2><p>Each new capture is compared item by item with the last one at the same store. Rises that a store makes on its own, out of step with its chain, are flagged for a closer look.</p>
  <h2>Data freshness</h2><p>This site rebuilds from static data exports. Current export: ${nzTime(m.generated)}. ${num(m.stores)} stores captured: ${CH.map(c=>`${c} ${m.chains[c].n}`).join(', ')}. The national capture is still running, so some stores and towns are not in yet.</p>
  <h2>Limits</h2><p>Online prices can differ from the shelf in store. Store locations are approximate. Some FreshChoice listings carry no pack size, so FreshChoice matches fewer products. Errors are possible; tell us and we will fix them.</p></div>`};
R.legal=()=>{setTitle('Legal and disclaimer');main.innerHTML=`<div class="ph prose"><p class="kicker">Legal</p><h1 style="font-size:clamp(36px,7vw,64px)">Legal and disclaimer</h1></div><div class="prose">
  <p>Prices are as captured from each retailer's public website on the date shown. They may have changed since and may differ from the price in store.</p>
  <p>Shelf Audit is independent. It is not affiliated with, endorsed by or paid by Woolworths, Foodstuffs, Pak'nSave, New World, FreshChoice, SuperValue, Fonterra or any other company named.</p>
  <p>Nothing here is financial, legal or purchasing advice. Words like "flagged", "under watch" and "Upticker" describe patterns in our data that may merit a closer look. They are not findings or allegations of wrongdoing.</p>
  <p>References to regulatory cases describe published outcomes only. Estimates of where money goes in the dairy chain are our modelling from public figures and are labelled as estimates.</p>
  <p>Trade marks belong to their owners and are used only to identify products and stores. If you think something here is wrong, contact us and we will review it promptly.</p></div>`};
R.about=()=>{setTitle('About');main.innerHTML=`<div class="ph prose"><p class="kicker">About</p><h1 style="font-size:clamp(36px,7vw,64px)">Shoppers deserve the receipt before the shop</h1></div><div class="prose">
  <p>Shelf Audit started in Whanganui after the October 2026 Pak'nSave pricing fines. The question was simple: if one store can get it wrong, how would anyone know which stores charge more for the same thing?</p>
  <p>So we started reading every shelf price, at every store we can reach, and comparing like with like. The result is the first store-by-store price index for New Zealand supermarkets that anyone can use.</p>
  <p>What it gives you: the cheapest store near you for what you actually buy, a record of who raises prices, and a plain look at where your dairy dollar goes.</p>
  <p>Built and run independently in Aotearoa New Zealand. Free to use.</p></div>`};


let NZM;const nzmap=()=>NZM??=fetch('/data/nzmap.json').then(r=>r.json());
async function mapSection(el){const g=await nzmap(),[x0,x1,y0,y1]=g.b,W=g.W,H=g.H,X=lo=>(lo-x0)/(x1-x0)*W,Y=la=>(y1-la)/(y1-y0)*H;
  const st=D.stores.filter(s=>s.la!=null),miss=D.stores.length-st.length;
  const col=ix=>{if(ix==null)return '#8d857a';const t=Math.max(-1,Math.min(1,(ix-100)/12));return t<0?`color-mix(in srgb,var(--green) ${Math.round(-t*100)}%,#c9c1b3)`:`color-mix(in srgb,var(--red) ${Math.round(t*100)}%,#c9c1b3)`};
  const regs=[...new Set(st.map(s=>s.r).filter(Boolean))].sort();
  el.innerHTML=`<p class="kicker">Map</p><h2>Every store we capture</h2><p class="say">${num(st.length)} stores, coloured by price index. Drag to move, pinch or scroll to zoom, tap a dot for the store.</p>
  <div class="chips" id="mch">${CH.map(c=>`<button class="chip" aria-pressed="true" data-c="${esc(c)}">${esc(c)}</button>`).join('')}</div>
  <div class="chips" id="mrg"><button class="chip" data-r="">All of New Zealand</button>${regs.map(r=>`<button class="chip" data-r="${esc(r)}">${esc(r)}</button>`).join('')}</div>
  <div class="nzmap"><svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Map of New Zealand supermarkets"><g id="mg"><path class="land" d="${g.d}"/>${st.map((s,i)=>`<circle class="dot" tabindex="0" data-s="${s.id}" cx="${X(s.lo).toFixed(1)}" cy="${Y(s.la).toFixed(1)}" r="3" style="fill:${col(s.ix)};animation-delay:${(i%120)*8+Math.round(Math.random()*200)}ms"/>`).join('')}</g></svg>
  <div class="mctl"><button aria-label="Zoom in" data-z="1.6">+</button><button aria-label="Zoom out" data-z="0.625">−</button><button aria-label="Reset map" data-z="0">Reset</button></div>
  <div class="mleg"><span>Cheaper</span><i></i><span>Dearer</span></div><div class="mtip" hidden></div></div>
  <p class="fine">${miss?`${miss} of ${D.stores.length} stores have no coordinates yet and are not shown. `:''}Colour runs from 12 points below to 12 points above the national median of 100. Locations are approximate. Coastline: Natural Earth.</p>`;
  const box=$('.nzmap',el),svg=$('svg',box),G=$('#mg',box),tip=$('.mtip',el),dots=$$('.dot',el);let on=null;
  let k=1,tx=0,ty=0,vx=0,vy=0,raf=0,anim=0;
  const unit=()=>{const r=svg.getBoundingClientRect();return Math.max(W/r.width,H/r.height)};
  const clamp=()=>{k=Math.max(1,Math.min(40,k));const m=.15;tx=Math.min(W*m,Math.max(W*(1-k)-W*m,tx));ty=Math.min(H*m,Math.max(H*(1-k)-H*m,ty))};
  const apply=()=>{clamp();G.setAttribute('transform',`translate(${tx.toFixed(2)} ${ty.toFixed(2)}) scale(${k.toFixed(4)})`);box.style.setProperty('--dr',(3/Math.sqrt(k)).toFixed(3));if(on)place(on)};
  const toSvg=(cx,cy)=>{const r=svg.getBoundingClientRect(),u=unit();return [(cx-r.left-(r.width-W/u)/2)*u,(cy-r.top-(r.height-H/u)/2)*u]};
  const zoomAt=(f,px,py)=>{const nk=Math.max(1,Math.min(40,k*f));f=nk/k;tx=px-(px-tx)*f;ty=py-(py-ty)*f;k=nk;apply()};
  const fly=(nk,ntx,nty)=>{cancelAnimationFrame(anim);cancelAnimationFrame(raf);const a={k,tx,ty},t0=performance.now();const s=t=>{const p=Math.min(1,(t-t0)/700),e=1-Math.pow(1-p,3);k=a.k+(nk-a.k)*e;tx=a.tx+(ntx-a.tx)*e;ty=a.ty+(nty-a.ty)*e;apply();if(p<1)anim=requestAnimationFrame(s)};anim=requestAnimationFrame(s)};
  const flyBox=(xs,ys)=>{const q=(a,f)=>{a=[...a].sort((x,y)=>x-y);return a[Math.min(a.length-1,Math.max(0,Math.round((a.length-1)*f)))]},lo=xs.length>6?.1:0,hi=1-lo;const bx0=q(xs,lo),bx1=q(xs,hi),by0=q(ys,lo),by1=q(ys,hi),pad=20;const nk=Math.max(1,Math.min(14,Math.min(W/(bx1-bx0+pad*2),H/(by1-by0+pad*2))));fly(nk,W/2-nk*(bx0+bx1)/2,H/2-nk*(by0+by1)/2)};
  const place=c=>{const b=box.getBoundingClientRect(),r=c.getBoundingClientRect();const l=r.left-b.left+r.width/2,t=r.top-b.top;
    tip.style.left=Math.max(8,Math.min(b.width-tip.offsetWidth-8,l-tip.offsetWidth/2))+'px';tip.style.top=(t-tip.offsetHeight-12<0?t+r.height+12:t-tip.offsetHeight-12)+'px'};
  const show=c=>{const s=store(+c.dataset.s);on?.classList.remove('on');on=c;c.classList.add('on');
    tip.innerHTML=`${chLogo(s.ch).replace('clogo','clogo big')}<span><strong>${esc(s.nm)}</strong><br><small>${esc(s.ch)} · index <b class="${cls(s.ix)}">${s.ix?s.ix.toFixed(1):'n/a'}</b>${s.thin?' · thin data':''}</small><br><a href="#/store/${s.id}">See store</a></span>`;tip.hidden=false;place(c)};
  const hide=()=>{tip.hidden=true;on?.classList.remove('on');on=null};
  // pointers: drag, pinch, inertia, tap
  const pts=new Map();let last=null,moved=0,pinch=null,lastTap=0;
  svg.addEventListener('pointerdown',e=>{svg.setPointerCapture(e.pointerId);pts.set(e.pointerId,[e.clientX,e.clientY]);cancelAnimationFrame(raf);cancelAnimationFrame(anim);vx=vy=0;moved=0;last={x:e.clientX,y:e.clientY,t:performance.now()};
    if(pts.size===2){const[a,b]=[...pts.values()];pinch={d:Math.hypot(a[0]-b[0],a[1]-b[1])}}});
  svg.addEventListener('pointermove',e=>{if(!pts.has(e.pointerId))return;pts.set(e.pointerId,[e.clientX,e.clientY]);const u=unit();
    if(pts.size===2&&pinch){const[a,b]=[...pts.values()],d=Math.hypot(a[0]-b[0],a[1]-b[1]),[px,py]=toSvg((a[0]+b[0])/2,(a[1]+b[1])/2);zoomAt(d/pinch.d,px,py);pinch.d=d;moved=9;return}
    const dx=(e.clientX-last.x)*u,dy=(e.clientY-last.y)*u,now=performance.now(),dt=Math.max(1,now-last.t);moved+=Math.abs(dx)+Math.abs(dy);tx+=dx;ty+=dy;vx=dx/dt*16;vy=dy/dt*16;last={x:e.clientX,y:e.clientY,t:now};apply()});
  const up=e=>{pts.delete(e.pointerId);if(pts.size<2)pinch=null;if(pts.size)return;
    if(moved<4*unit()){const c=document.elementFromPoint(e.clientX,e.clientY)?.closest?.('.dot');const now=performance.now();
      if(now-lastTap<300&&!c){const[px,py]=toSvg(e.clientX,e.clientY);fly(Math.min(40,k*2),px-(px-tx)*Math.min(40,k*2)/k,py-(py-ty)*Math.min(40,k*2)/k)}
      lastTap=now;c?show(c):hide();return}
    const step=()=>{vx*=.92;vy*=.92;tx+=vx;ty+=vy;apply();if(Math.abs(vx)+Math.abs(vy)>.05)raf=requestAnimationFrame(step)};raf=requestAnimationFrame(step)};
  svg.addEventListener('pointerup',up);svg.addEventListener('pointercancel',up);
  svg.addEventListener('wheel',e=>{e.preventDefault();const[px,py]=toSvg(e.clientX,e.clientY);zoomAt(Math.exp(-e.deltaY*.0018),px,py)},{passive:false});
  svg.addEventListener('dblclick',e=>e.preventDefault());
  dots.forEach(c=>{c.addEventListener('mouseenter',()=>{if(!pts.size)show(c)});c.addEventListener('focus',()=>show(c))});
  $$('.mctl button',el).forEach(b=>b.onclick=()=>{const z=+b.dataset.z;if(!z)return fly(1,0,0);const nk=Math.max(1,Math.min(40,k*z));fly(nk,W/2-(W/2-tx)*nk/k,H/2-(H/2-ty)*nk/k)});
  $$('#mch .chip',el).forEach(b=>b.onclick=()=>{b.setAttribute('aria-pressed',b.getAttribute('aria-pressed')!=='true');const offc=new Set($$('#mch .chip',el).filter(x=>x.getAttribute('aria-pressed')==='false').map(x=>x.dataset.c));dots.forEach(d=>{const x=offc.has(store(+d.dataset.s).ch);if(!x&&d.classList.contains('off'))d.classList.add('re');d.classList.toggle('off',x)});if(on&&on.classList.contains('off'))hide()});
  $$('#mrg .chip',el).forEach(b=>b.onclick=()=>{const r=b.dataset.r;hide();if(!r)return fly(1,0,0);const s=st.filter(x=>x.r===r);flyBox(s.map(x=>X(x.lo)),s.map(x=>Y(x.la)))});
  apply()}


// category x chain heat grid
async function catGrid(el,order){try{const I=await intel();if(!el.isConnected||!I.chaincat)return;const cc=I.chaincat;
  const cats=[...new Set(Object.values(cc).flatMap(o=>Object.keys(o)))].sort();
  const bg=v=>{const d=Math.max(-15,Math.min(15,v-100))/15;return d>0?`rgba(255,74,54,${(.15+.6*d).toFixed(2)})`:`rgba(61,220,151,${(.15+.6*-d).toFixed(2)})`};
  const cap=I.cap?new Date(I.cap).toLocaleDateString('en-NZ',{day:'numeric',month:'long',year:'numeric',timeZone:'Pacific/Auckland'}):'';
  const head=order.map(n=>`<th style="border-top:6px solid ${CHCOL[n]}">${esc(n)}</th>`).join('');
  const rows=cats.map(c=>{const vals=order.map(n=>cc[n]&&cc[n][c]);const ok=vals.filter(v=>v!=null),mn=Math.min(...ok);
    return `<tr><th scope="row">${esc(c)}</th>${vals.map(v=>v==null?'<td class="na">No data</td>':`<td style="background:${bg(v)}"${v===mn?' class="best"':''}>${v.toFixed(1)}${v===mn?' <span>cheapest</span>':''}</td>`).join('')}</tr>`}).join('');
  el.innerHTML=`<h3 style="margin:26px 0 6px">Price index by aisle, every chain</h3><p class="say" style="font-size:16px">Each chain's typical price for the same products in each category, against the national median of 100. Lower is cheaper. Columns run dearest to cheapest overall.</p><div class="cgwrap"><table class="cg"><thead><tr><th>Category</th>${head}</tr></thead><tbody>${rows}</tbody></table></div><p class="fine">Source: Shelf Audit shelf price capture${cap?', '+cap:''}, ${cats.length} categories. Median shelf price per product, stores with full data only. FreshChoice has no category data yet because too few of its products match across stores.</p><div class="nwcall"><p>In case you think New World are great and this must be a glitch: it's not. It's every category, and all 125 branches. Higher prices are a choice, and it's your wages paying for it.</p><small>All 125 New World stores price above the national median (101.4 to 106.6), capture 1 November 2026.</small></div>`;stBars($('#stbars'))}catch(e){el.hidden=true}}
function chPct(c){const w=(D.stores||[]).filter(s=>s&&s.ch===c&&s.ix!=null);return w.length?Math.round(w.filter(s=>s.ix>100).length/w.length*100):null}
function chGrade(p){return p<=10?'A':p<=25?'B':p<=40?'C':p<=60?'D':p<=80?'E':'F'}
function stGrade(ix){return ix<90?'A':ix<95?'B':ix<=100?'C':ix<=103?'D':ix<=106?'E':'F'}
function stamp(c){const p=chPct(c);if(p==null)return '';const g=chGrade(p),ok='ABC'.includes(g);return `<div class="stamp ${ok?'ok':'no'}"><b>${g}</b><span><strong>${ok?'PASS':'FAIL'}</strong><small>TESTED ACROSS NZ</small>${c==='FreshChoice'?'<em>thin data</em>':''}</span></div>`}
function stBars(el){if(!el)return;const ord=['New World','Woolworths',"Pak'nSave",'FreshChoice'].sort((a,b)=>chGrade(chPct(a)??101).localeCompare(chGrade(chPct(b)??101))||(chPct(a)??101)-(chPct(b)??101)),lo=80,hi=110,pc=v=>Math.max(0,Math.min(100,(v-lo)/(hi-lo)*100));
const grp=ord.map(c=>{const L=D.stores.filter(s=>s&&s.ch===c).sort((a,b)=>(b.ix??-1)-(a.ix??-1)),w=L.filter(s=>s.ix!=null),up=w.filter(s=>s.ix>100).length;
return `<div class="sbg"><div class="sbh">${chLogo(c).replace('class="clogo','class="clogo sbl').replace('height="24"','height="40"')}<h4>${esc(c)}</h4><div class="sbpct"><b class="${(w.length-up)/w.length>=.5?'g':'r'}">${Math.round((w.length-up)/w.length*100)}%</b><span>of stores at or below median<br>${w.length-up} of ${w.length} stores${L.length>w.length?`, ${L.length-w.length} with no data`:''}</span></div>${stamp(c)}</div><div class="sbgrid">${L.map((s,i)=>`<a class="sbc${i>=12?' more':''}" href="#/store/${s.id}"><span class="trk"><span class="fill ${s.ix==null?'na':s.ix>100?'up':'ok'}" style="width:${s.ix==null?100:pc(s.ix)}%"></span><span class="mid" style="left:${pc(100)}%"></span></span><span class="nm">${esc(s.nm)}</span>${s.ix==null?'<i></i>':`<i class="sg ${'ABC'.includes(stGrade(s.ix))?'ok':'no'}">${stGrade(s.ix)}</i>`}<b class="v">${s.ix==null?'n/a':s.ix.toFixed(1)}</b></a>`).join('')}</div>${L.length>12?`<button class="sbmore" type="button">Show all ${L.length} ${esc(c)} stores</button>`:''}</div>`}).join('');
const NA=D.stores.filter(s=>s),NW=NA.filter(s=>s.ix!=null),NU=NW.filter(s=>s.ix>100).length,NUp=Math.round(NU/NW.length*1000)/10,NDp=Math.round((100-NUp)*10)/10;
const nat=`<div class="natl"><p class="natl-h">Across all ${NW.length} priced NZ supermarkets, every brand:</p><div class="natl-n"><div><b class="r">${NUp}%</b><span>price above the median<br>${NU} stores</span></div><div><b class="g">${NDp}%</b><span>at or below the median<br>${NW.length-NU} stores</span></div></div><div class="natl-bar"><i style="width:${NUp}%"></i><i style="width:${NDp}%"></i></div><p class="fine">Source: Shelf Audit shelf price capture, 1 November 2026. ${NW.length} stores with a price index, national median 100. ${NA.length-NW.length} of ${NA.length} stores had no data and are not counted.</p></div>`;
el.innerHTML=`${nat}<h3>Every store, every chain</h3><p class="sbkey"><span class="k up"></span>Above national median <span class="k ok"></span>At or below <span class="k na"></span>No data. Bars run from 80 to 110, the line marks the median of 100.</p>${grp}<p class="fine">Source: Shelf Audit shelf price capture, 1 November 2026. Each bar is one store's price index, sorted dearest to cheapest within its chain. FreshChoice figures are from thin data (few matching products per store).</p><p class="fine">Chain grade, by share of stores above the national median: A 0 to 10%, B 11 to 25%, C 26 to 40% (PASS); D 41 to 60%, E 61 to 80%, F 81 to 100% (FAIL). Store grade, by price index: A under 90, B 90 to 94.9, C 95 to 100 (PASS); D 100.1 to 103, E 103.1 to 106, F over 106 (FAIL).</p>`;
el.querySelectorAll('.sbmore').forEach(b=>b.addEventListener('click',()=>{const g=b.parentElement;g.classList.toggle('open');b.textContent=g.classList.contains('open')?'Show fewer':`Show all ${g.querySelectorAll('.sbc').length} stores`}))}
