R.api=async()=>{setTitle('API');const I=await intel();const g=I.gaps[0],p=D.products[g[0]];const ex=(u,o)=>`<p class="kicker">GET <a href="${u}">${u}</a></p><pre class="code">${esc(JSON.stringify(o,null,2)).slice(0,900)}</pre>`;
  const s0=D.stores[0];const host=location.origin;
  main.innerHTML=`<div class="ph prose"><p class="kicker">Shelf Audit API</p><h1 style="font-size:clamp(36px,7vw,64px)">Know every shelf price in New Zealand before your shoppers do</h1><p class="lede">${D.meta.stores} New Zealand supermarkets, ${D.products.length.toLocaleString('en-NZ')} matched products. Benchmarks for supermarkets, evidence for regulators.</p><p><a class="btn" href="#enq">Request access</a> <a class="btn ghost" href="/api/v1/gaps.json">Try the open API</a></p><div class="stats"><div><b>${D.meta.stores}</b><span>stores</span></div><div><b>${D.products.length.toLocaleString('en-NZ')}</b><span>matched products</span></div><div><b>${(D.meta.prices/1e6).toFixed(1)} million</b><span>prices captured</span></div><div><b>4</b><span>chains</span></div></div></div>
<div class="prose"><section class="blk"><p class="kicker">For supermarkets</p><h2>Price more intelligently</h2><p>See where you sit against competitors and neighbouring stores: chain and regional benchmarks, a price index by aisle, and store-level spreads on identical products. Useful for spotting a shelf that has drifted out of line before shoppers do.</p></section>
<section class="blk"><p class="kicker">For regulators</p><h2>We are here to help</h2><p>Helping agencies such as the Commerce Commission find stores that have not quite got the hang of honest pricing yet. We flag patterns worth a closer look, with the evidence, so attention goes where it is most useful. Shelf Audit is independent and has no partnership with, or endorsement from, any agency or supermarket.</p></section>
<section class="blk"><h2>Open endpoints</h2><p>Static JSON, no key needed. Captured ${esc(new Date(D.meta.last).toLocaleDateString('en-NZ',{day:'numeric',month:'long',year:'numeric'}))}.</p>
<ul><li><code>/api/v1/stores.json</code> every store with chain, town, region, location and index</li><li><code>/api/v1/products/{id}.json</code> one product: median, range, chain medians, regular price range by chain, cheapest stores</li><li><code>/api/v1/index.json</code> chain index, chain by aisle, regions</li><li><code>/api/v1/gaps.json</code> largest regular-price gaps, products in 40+ stores</li></ul>
${ex('/api/v1/gaps.json',{captured:I.cap,gaps:[{product_id:g[0],product:p[0],cheapest:{price:g[1],store:{id:g[2],name:D.stores[g[2]]?.nm}},dearest:{price:g[3],store:{id:g[4],name:D.stores[g[4]]?.nm}},gap:+(g[3]-g[1]).toFixed(2),stores:g[5]},'...']})}
${ex('/api/v1/products/'+g[0]+'.json',{id:g[0],name:p[0],brand:p[1],category:p[2],median:p[3],min:p[4],max:p[5],stores:p[6],chain_median:p[7],'...':''})}
${ex('/api/v1/stores.json',{count:D.stores.length,stores:[{id:s0.id,chain:s0.ch,name:s0.nm,town:s0.t,region:s0.r,index:s0.ix},'...']})}
<p>Example: <code>curl ${esc(host)}/api/v1/gaps.json</code></p></section>
<section class="blk"><h2>Coverage, updates and method</h2><p>Coverage: ${D.meta.stores} stores across Woolworths, Pak'nSave, New World and FreshChoice; ${D.meta.full} with full captures. FreshChoice data is thin and left out of chain comparisons. Some stores lack map coordinates.</p><p>Updates: captures are currently run manually, not on a fixed schedule. Each file carries its capture date. There is no price history yet, so changes over time are not available.</p><p>Method: identical products are matched across stores by barcode and name. Index 100 is the Woolworths national basket. Gaps use regular shelf prices with specials removed. Anything unusual is flagged for a closer look, never assumed. <a href="#/method">Full method</a></p></section>
<section class="blk"><p class="kicker">Pricing</p><h2>Pick your coverage</h2><div class="prices">
<div class="pcard"><p class="kicker">Local</p><p class="pbig">$595<small> / month + GST</small></p><p>Every store within a 50km radius of your location.</p><ul><li>Competitor and regional benchmarks</li><li>Index by aisle</li><li>Store-level spreads on identical products</li></ul><p class="note">Monthly, per calendar month.</p><a class="btn ghost" href="#enq" data-plan="Local">Request access</a></div>
<div class="pcard feat"><p class="kicker">National · most popular</p><p class="pbig">$1,850<small> / month + GST</small></p><p>All ${D.meta.stores} stores in New Zealand.</p><p class="pann">Or $1,450 / month + GST paid annually ($17,400 + GST a year). Save $4,800 a year.</p><ul><li>Everything in Local, nationwide</li><li>Chain and region comparisons</li><li>Flagged pricing patterns with evidence</li></ul><a class="btn" href="#enq" data-plan="National">Request access</a></div>
</div><p class="fine">Annual pricing currently applies to National only. No payment is taken online; we set up access after a conversation. The open endpoints above stay free.</p></section>
<section class="blk" id="enq"><h2>Request access</h2><p>Or email <a href="mailto:guy.hollister@gmail.com">guy.hollister@gmail.com</a>.</p>
<form class="sform" id="enqf">${fld('Name','<input name="name" required>')}${fld('Organisation','<input name="org">')}${fld('Email','<input name="email" type="email" required>')}${fld('Interested in','<select name="kind"><option>National plan</option><option>Local plan</option><option>Supermarket benchmarks</option><option>Regulator</option><option>Research or media</option><option>Other</option></select>')}${fld('Message','<textarea name="msg" rows="4"></textarea>')}<input name="website" class="hp" tabindex="-1" autocomplete="off" aria-hidden="true"><div class="ts"></div><button class="btn" type="submit">Send enquiry</button><p class="fmsg" role="status"></p></form></section></div>`;
  main.querySelectorAll('a[href="#enq"]').forEach(a=>a.onclick=e=>{e.preventDefault();if(a.dataset.plan)$('#enqf').kind.value=a.dataset.plan==='Local'?'Local plan':'National plan';$('#enq').scrollIntoView({behavior:'smooth'})});
  const f=$('#enqf');wireForm(f,async fd=>{await post('enquiry',fd);f.innerHTML='<h2>Thanks, enquiry received.</h2><p class="say">Guy will be in touch.</p>'})};

function fieldFor(k,id){const f=(D.field||[]).filter(x=>x[k]===id);if(!f.length)return '';return `<div class="vshelf">${f.map(x=>`<p><span class="badge ${x.m?'ok':'flag'}">${x.src==='receipt_photo'?'✓ Checked on receipt':'✓ Verified on shelf'}</span> <span class="note">${money(x.pr)}${x.w?` (was ${money(x.w)})`:''} ${x.src==='receipt_photo'?'charged':''} at <a href="#/store/${x.s}">${esc(store(x.s).nm)}</a>, ${x.src==='receipt_photo'?'receipt':'photographed'} ${nzDate(x.at)}. ${x.m?'Matches the online price.':`Online showed ${money(x.op)}${x.l?' ('+esc(x.l)+')':''}. Flagged for comparison only.`}</span></p>`).join('')}</div>`}
function fieldStore(id){const f=(D.field||[]).filter(x=>x.s===id);if(!f.length)return '';const ok=f.filter(x=>x.m).length;return `<details class="vshelf"><summary><span class="badge ok">✓ Verified on shelf</span> <span class="note">Field checks: ${f.length} prices checked in store (shelf tickets and receipts), ${ok} of ${f.length} match online</span></summary><ul class="plist">${f.map(x=>`<li><span class="pn">${x.p!=null?`<a href="#/p/${x.p}">${esc(x.n)}</a>`:esc(x.n)}${x.l?`<small>Ticket: ${esc(x.l)}</small>`:''}</span><span class="range"><span class="${x.w?'dn':''}">${money(x.pr)}</span><br><small>${x.src==='receipt_photo'?'receipt · ':''}${x.m?'matches online':'<span class="up">online '+money(x.op)+'</span>'}</small></span></li>`).join('')}</ul></details>`}


// Real-life cost of a dear store. Public figures only, see #/method "What a dear store costs".
const LIFE={basket:214.10,min:23.95,med:35.96,living:29.90,milk:5.68,bread:3.99,eggs:7.40};
function lifeCost(pct,vs){if(!(pct>0.5))return '';const L=LIFE,wk=L.basket*pct/100,yr=wk*52,mins=Math.round(wk/L.min*60),hy=yr/L.min;
  return `<div class="life"><p class="life-k">What this costs a household</p>
  <p class="life-big"><b>${money(wk)}</b> a week · <b>$${num(Math.round(yr))}</b> a year</p>
  <p class="life-s">extra on a typical supermarket shop, ${pct.toFixed(1)}% above ${esc(vs)}.</p>
  <ul class="life-l"><li><b>${mins} min</b> of work every week at the minimum wage just to cover the gap. <b>${Math.round(hy)} hours</b> a year.</li>
  <li>That is <b>${Math.floor(yr/L.milk)}</b> bottles of 2L milk, or <b>${Math.floor(yr/L.bread)}</b> loaves of bread, or <b>${Math.floor(yr/L.eggs)}</b> dozen eggs a year that the money no longer buys.</li>
  <li>At the median wage it is <b>${Math.round(yr/L.med)} hours</b> of work a year. On the minimum wage it is <b>${(hy/40).toFixed(1)} weeks</b> of full-time pay.</li></ul>
  <p class="life-f">Typical shop $${L.basket.toFixed(2)} a week (Stats NZ, 2023). Minimum wage $${L.min} an hour, median $${L.med}. Estimate only. <a href="#/method">How we work it out</a></p></div>`}


// Lines where a store sits above the national median, store price vs NZ median, regular prices only
async function overList(id,el,n=12,dark){if(!el)return;const P=await storePrices(id),pr=D.products;
  const rows=Object.entries(P).filter(([i,v])=>!Array.isArray(v)&&pr[i]&&pr[i][6]>=5&&v-pr[i][3]>=0.2).map(([i,v])=>[+i,v,pr[i][3]]).sort((a,b)=>(b[1]/b[2])-(a[1]/a[2])).slice(0,n);
  const tot=Object.entries(P).filter(([i,v])=>!Array.isArray(v)&&pr[i]&&pr[i][6]>=5&&v>pr[i][3]+0.005).length;
  if(!rows.length){el.innerHTML='';return}
  el.innerHTML=`<details class="ovl${dark?' dk':''}"><summary class="life-k">Priced above the NZ median: ${num(tot)} lines <span class="op">Open</span></summary><table><thead><tr><th>Product</th><th class="n">This store</th><th class="n">NZ median</th><th class="n">Extra</th></tr></thead><tbody>${rows.map(([i,v,m])=>`<tr><td><a href="#/p/${i}">${esc(pr[i][0])}</a></td><td class="n up">${money(v)}</td><td class="n">${money(m)}</td><td class="n up">+${Math.round((v/m-1)*100)}%</td></tr>`).join('')}</tbody></table><p class="life-f">Regular shelf prices, specials removed. NZ median is the middle price across every store that sells the item (5 or more stores). Flagged for comparison only.</p></details>`}


// Cheaper stores near the worst store: road drive time (OpenStreetMap via OSRM) and weekly saving, baked by scripts/build_report.py
function nearSave(w){const n=w.near||[];if(!n.length)return '';const b=n.reduce((a,x)=>x.wk>a.wk?x:a,n[0]);
  return `<details class="ovl dk near"><summary class="life-k">Drive a few minutes, save money <span class="op">Open</span></summary><p class="life-s">Shopping at <a href="#/store/${b.id}">${esc(b.nm)}</a>, ${b.min} min away, instead saves about <b>${money(b.wk)}</b> a week, <b>$${num(Math.round(b.wk*52))}</b> a year.</p>
  <table><thead><tr><th>Cheaper store nearby</th><th class="n">Drive</th><th class="n">Distance</th><th class="n">Save a week</th><th class="n">Save a year</th></tr></thead><tbody>${n.map(x=>`<tr><td>${chLogo(x.ch)} <a href="#/store/${x.id}">${esc(x.nm)}</a></td><td class="n">${x.min} min</td><td class="n">${x.km} km</td><td class="n up">${money(x.wk)}</td><td class="n up">$${num(Math.round(x.wk*52))}</td></tr>`).join('')}</tbody></table>
  <p class="life-f">Drive time and distance one way by road from ${esc(w.nm)}, from OpenStreetMap road data (OSRM router), normal traffic not included. Saving = typical weekly shop $${LIFE.basket.toFixed(2)} × the gap in national price index between the two stores (${w.nat.toFixed(1)} here). Fuel not included. Estimate only.</p></details>`}


// Pak'nSave vs FreshChoice: yearly gap = typical weekly shop x index gap x 52
function pnsGap(w){const L=LIFE;const nn=w.near||[];const ns=nn.length?nn.reduce((a,x)=>x.wk>a.wk?x:a,nn[0]):null;
  const med=a=>{a=a.filter(v=>v>0).sort((x,y)=>x-y);return a.length?a[a.length>>1]:null};
  const S=(typeof D!=='undefined'&&D&&D.stores)||[];const cm=c=>med(S.filter(s=>s.ch===c).map(s=>s.ix));
  const pi=cm("Pak'nSave"),fi=cm('FreshChoice');const rows=[];let hero='';
  if(ns&&w.nat>ns.nat){const g=w.nat-ns.nat,wk=Math.round(L.basket*g)/100;hero=`<div class="gaphero"><div class="gh-vs"><span class="gh-s"><span class="gh-gr g${w.g}">${w.g}</span><span class="gh-a">${esc(w.nm)}</span></span><span class="gh-v">vs</span><span class="gh-s">${ns.g?`<span class="gh-gr g${ns.g}">${ns.g}</span>`:''}<a class="gh-b" href="#/store/${ns.id}">${esc(ns.nm)}</a></span></div><div class="gh-pair"><div class="gh-hero"><b>$${num(Math.round(wk*52))}</b><i>more a year at ${esc(w.nm)}</i></div><div class="gh-dist"><b>${ns.km}</b><em>km</em><span>${ns.min} min drive</span></div></div><div class="gh-row"><div><b>${money(wk)}</b><i>a week</i></div><div><b>${g.toFixed(1)}%</b><i>dearer</i></div><div><b>${w.nat.toFixed(1)} / ${ns.nat.toFixed(1)}</b><i>national index</i></div></div>${/papakura/i.test(w.nm)?(()=>{const y=Math.round(wk*52),pc=v=>(y/v*100).toFixed(1);return `<div class="gh-loc"><p class="gh-lk">What that saving covers in Papakura</p><div class="gh-row"><div><b>${pc(4378)}%</b><i>of a year's council rates (Auckland average home, $4,378)</i></div><div><b>${pc(530*52)}%</b><i>of a year's rent (Papakura median, $530 a week)</i></div><div><b>${pc(44000)}%</b><i>of median adult income ($44,000)</i></div></div><p class="life-f">Sources: Auckland Council Annual Plan 2026/2027, average-value residential rates $4,378 a year (Auckland-wide; Papakura values are lower, so its share of a Papakura bill is likely higher). Stats NZ 2023 Census, Papakura Local Board: median weekly rent $530, median adult personal income $44,000, median household income $111,500 (saving = ${pc(111500)}%).</p></div>`})():''}</div>`}
  // Chain-typical row removed: one Papakura figure only (same national-index math as the hero)
  if(!rows.length&&!hero)return '';
  return `<div class="ovl dk gapbox"><p class="life-k">Nearest cheaper competitor: drive ${ns?ns.km+' km':'a few minutes'}, save ${ns?'$'+num(Math.round(Math.round(L.basket*(w.nat-ns.nat))/100*52)):''} a year</p>${hero}<p class="life-f">Yearly gap = typical weekly shop $${L.basket.toFixed(2)} × gap in national price index ÷ 100 × 52 weeks. Same figure as the drive-and-save block. Estimate only.</p></div>`}

// Report card: worst-priced store in NZ. Data baked by scripts/build_report.py
// One source of truth for a store's cost: the national index from report.json (same as the report card).
async function storeNat(s){try{REP??=await fetch('/data/report.json').then(r=>r.json())}catch{return}
  const x=REP.nx?.[s.id];if(!x)return;const [nat,n]=x,c=$('#scost'),st=$('.stats .stat b'),th=$('#sthin');if(!c)return;
  if(st){st.textContent=nat.toFixed(1);st.className=cls(nat);st.nextElementSibling.textContent='national price index'}
  const sw=$('#sword');if(sw)sw.textContent=`On identical products, this store is ${ixWord(nat)}.`;
  if(th)th.textContent=`National index ${nat.toFixed(1)} from ${num(n)} matched products on regular shelf prices, the same figure used in the report card.`;
  c.innerHTML=nearCost(REP.top.find(t=>t.id==s.id),nat)}
function nearCost(w,nat){const n=((w&&w.near)||[]).filter(x=>nat>x.nat);if(!n.length)return lifeCost(nat-100,'the typical NZ price for the same products');const b=n.reduce((a,x)=>x.wk>a.wk?x:a,n[0]);return lifeCost(Math.round(LIFE.basket*(nat-b.nat))/LIFE.basket,b.nm+', the nearest cheaper competitor ('+b.km+' km away)')}
let REP;async function reportCard(){const el=$('#rcard');if(!el)return;try{REP??=await fetch('/data/report.json').then(r=>r.json())}catch{return}
  const w=REP.top[0];if(!w)return;const lk=x=>x.id!=null?`href="#/store/${x.id}"`:'';const pct=v=>(v-100).toFixed(1)+'%';
  el.innerHTML=`<section class="rc" aria-label="Worst pricing in New Zealand">
  <div class="rc-in"><h1 class="rc-k rc-t"><span>Shelf Audit report card</span><span>Worst pricing in NZ</span></h1>
  <div class="rc-main">
   <div class="rc-b"><div class="rc-hd"><div class="rc-g" aria-label="Grade ${w.g}"><span>${w.g}</span><small>Fail</small></div>${heroLogo(w.ch)}</div><h2><a ${lk(w)}>${esc(w.nm)}</a></h2>
   <p class="rc-s"><b>${w.nat.toFixed(1)}</b> national price index · ${pct(w.nat)} above the typical NZ price for the same products (${w.ix.toFixed(1)} against its own chain)</p>
   <p class="rc-e">Typical line ${w.med}% above its own chain. ${num(w.o20)} products flagged more than 20% dearer (${w.o20p}% of ${num(w.n)} checked).${w.ex?` Example: ${esc(w.ex.p)} ${money(w.ex.v)} vs ${money(w.ex.m)} chain median.`:''}</p>
   
   ${nearCost(w,w.nat)}
   ${pnsGap(w)}
   ${nearSave(w)}
   ${w.id!=null?'<div id="rcov"></div>':''}
   ${w.id!=null?`<a class="rc-btn" ${lk(w)}>See the evidence</a>`:''}</div></div>
  <ol class="rc-top">${REP.top.map(x=>`<li><a ${lk(x)}><span class="rc-r">${x.rank}</span><span class="rc-gg g${x.g}">${x.g}</span>${chLogo(x.ch||chOf(x.nm))}<span class="rc-n">${esc(x.nm)}</span><span class="rc-x">${x.ix.toFixed(1)}</span></a></li>`).join('')}</ol>
  <p class="rc-f">Grade scale: score is the store's regular shelf price index against its own chain, 100 = chain median for the same products. A under 99 · B 99 to 101 · C 101 to 103 · D 103 to 105 · F 105 and over. Of ${num(REP.stores)} stores graded: ${Object.entries(REP.dist).map(([g,n])=>`${g} ${num(n)}`).join(', ')}. Specials removed. Flagged lines are for comparison, not an allegation. <a href="#/method">Method</a></p></div></section>`;if(w.id!=null)overList(w.id,$('#rcov'),8,1)}
